
gsap.registerPlugin(ScrollTrigger);

function initNumberTrainGSAP() {
  const trains = document.querySelectorAll('.track_train_container');

  trains.forEach((train) => {
    const track = train.querySelector('.number_track');
    if (!track) return;

    // Ambil data atribut
    const value = Math.max(0, Math.min(9, parseInt(train.dataset.number, 10)));
    const direction = (train.dataset.direction || 'up').toLowerCase();
    const duration = parseFloat(train.dataset.duration) || 1.5;
    const delay = parseFloat(train.dataset.delay) || 0;
    const startTrigger = train.dataset.start || 'top 90%';

    // Target posisi akhir (0 = 0%, 1 = -10%, ..., 9 = -90%)
    const targetY = -(value * 10);
    
    // Logika Pergerakan:
    // 'up'   -> start dari lebih rendah (y lebih positif)
    // 'down' -> start dari lebih tinggi (y lebih negatif)
    const offset = 30; // sejauh 3 angka
    let startY = (direction === 'up') ? targetY + offset : targetY - offset;

    // Batasi startY agar tidak keluar dari area angka (0 s/d -90)
    startY = Math.min(0, Math.max(-90, startY));

    // 1. Set posisi awal secara instan
    gsap.set(track, { yPercent: startY });

    // 2. Buat animasi ke targetY
    gsap.to(track, {
      yPercent: targetY,
      duration: duration,
      delay: delay,
      ease: "power4.out",
      scrollTrigger: {
        trigger: train,
        start: startTrigger,
        toggleActions: "play none none none", // Mainkan sekali saat terlihat
      }
    });
  });
}

// Jalankan setelah semua resource siap
window.addEventListener('load', initNumberTrainGSAP);
